(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.018+t*0.4)*20 + Math.cos(y*0.012-t*0.3)*15 + Math.sin((x+y)*0.008+t*0.15)*10;
  const wy = Math.cos(y*0.018-t*0.35)*20 + Math.sin(x*0.015+t*0.45)*15 + Math.cos((x-y)*0.009-t*0.2)*10;
  const sx = x + wx, sy = y + wy;
  const wells = [
    [160+Math.sin(t*0.5)*120, 80+Math.cos(t*0.35)*60, 8000],
    [320+Math.cos(t*0.45)*100, 160+Math.sin(t*0.6)*70, 6000],
    [240+Math.sin(t*0.3+2)*160, 120+Math.cos(t*0.4+1)*100, 10000],
    [100+Math.cos(t*0.7+1)*90, 200+Math.sin(t*0.5+3)*70, 5000],
    [380+Math.sin(t*0.35+4)*100, 50+Math.cos(t*0.8+2)*80, 7000],
    [240+Math.cos(t*0.3+5)*130, 210+Math.sin(t*0.5)*90, 9000]
  ];
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.1, 2.2],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.12, 1.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.08, 2.6],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.14, 1.6],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.09, 2.9],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.11, 2.1]
  ];
  let aS = 0, iS = 0, grav = 0;
  for (const [gX, gY, mass] of wells) {
    const d2 = (sx-gX)**2 + (sy-gY)**2;
    grav += mass / (d2 + 500);
  }
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const energy = grav * 0.001;
    aS += Math.sin(d*f - t*sp) * (1 + energy);
    iS += Math.sin(d*f*0.6 + t*sp*0.5 + 1.5) * (1 - energy*0.3);
  }
  const act = aS/6, inh = iS/6;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.9) + Math.sin(sx*0.028-sy*0.038+t*1.3))/2;
  const bg2 = Math.sin((sx+sy)*0.14+t*3)*0.3 + Math.sin((sx-sy)*0.11-t*2.5)*0.3;
  const bg3 = Math.sin(sx*0.06+t*1.5)*Math.cos(sy*0.05-t*1.2)*0.4;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const potential = Math.sin(dist*0.04 - t*0.8) * 0.5;
  const kinetic = Math.sin(ang*5 + dist*0.02 + t*2) * 0.5;
  const spiral = (Math.sin(dist*0.055-ang*4-t*1.8) + Math.sin(dist*0.04+ang*5-t*1.4))*0.45;
  const energyField = potential + kinetic;
  const rawReaction = act - inh*0.65 + bg*0.25 + spiral*0.3 + energyField*0.15;
  const reaction = Math.tanh(rawReaction * 3.5);
  const cell = Math.tanh((Math.sin(sx*0.18)*Math.sin(sy*0.18) + Math.sin((sx+sy)*0.12+t*1.2)*0.6)*2);
  const flow = Math.sin(sx*0.08+Math.sin(sy*0.05+t)*3+t*1.5) * Math.cos(sy*0.07+Math.cos(sx*0.04-t)*2.5-t);
  const blend = reaction*0.6 + cell*0.2 + flow*0.15 + Math.tanh(grav*0.05)*0.05;
  const v = blend*0.5+0.5;
  const pal = [
    [2,4,15],[5,15,45],[10,60,120],[0,180,200],[50,255,180],
    [255,240,60],[255,100,40],[255,30,80],[200,0,150],[80,0,180],[20,5,40],[2,4,15]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const edgeIntensity = Math.abs(reaction);
  const glow = edgeIntensity > 0.6 ? (edgeIntensity - 0.6)*2.5 : 0;
  const lum = 0.7 + Math.sin(reaction*Math.PI)*0.3 + glow*0.5;
  const edge = edgeIntensity > 0.75 ? 1.3 + glow*0.4 : 1.0;
  const gravGlow = Math.min(1, grav*0.003);
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + gravGlow*20)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + gravGlow*30)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + gravGlow*50)|0)
  ];
}
